import{_ as t,o as l,c as n,j as e,a as r}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第64章 零点","description":"","frontmatter":{},"headers":[],"relativePath":"第64章_零点.md","filePath":"第64章_零点.md"}'),o={name:"第64章_零点.md"};function s(p,a,_,c,d,i){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"第64章-零点",tabindex:"-1"},[r("第64章 零点 "),e("a",{class:"header-anchor",href:"#第64章-零点","aria-label":'Permalink to "第64章 零点"'},"​")],-1),e("p",null,"我这四年没有在十一点以前睡过。这件事我跟谁都没说过。我跟她那边对出来的时间是：我这边零点，是她那边下午五点。下午五点是她们一天里最乱的时候，课刚上完，人要走去下一个地方，要么在公交上，要么在超市排队，要么在食堂找位置。她一天里最不像她的话，全在那一个钟头。我为什么知道她那时候最不像她，因为那一个钟头她发的东西是碎的。她会说：今天风好大。然后过三分钟：我刚在车上差点坐过站。再过两分钟：我这里有个男生在讲电话，讲得超大声音。再过一分钟：啊不是，我在跟你说话，我在抱怨我自己的日子。她说完了以后会补一句，说她今天讲话好琐碎。我说，挺好的。她说，你听得下去？我说，我这边十二点，我什么都不用干。我这边十二点确实什么都不用干，宿舍熄灯，屋子安静，呼噜起来了，郑拓的键盘也停了。整个世界只有我这边一个人醒着，而那个醒着的人正在听一个下午五点的人讲她今天差点坐过站。",-1),e("p",null,'我算过一次。我从大一九月熬到大二六月，两个学期，按每晚平均多醒一小时四十分钟算，除掉寒暑假，在校天数大约二百二十天。二百二十乘以一百分钟，三百六十多个小时。我把这个数写在本子上，写完自己看着想笑——三百六十个小时，一个人可以拿三百六十个小时学一门语言，练一项技术，考一张证，我拿它换来听一个人说"今天风好大"。而且这笔账没人能跟我算，它不占我任何一张单子，不出现任何一次，没有一个地方能写"我为了一个人熬了三百六十小时"，它只存在于一个我从不给人看的本子里，而且她不知道，她一直以为我晚上本来就不睡。',-1),e("p",null,'有一次她问我，说你为什么每天这个时候都在。我说，我刚好没睡。她说，你天天刚好？我说，我睡眠差。她说，那你去看医生。我说，不用。她说，你这个人，你什么都"不用"。那天我撒了谎，我撒的是一个不需要一点力气的谎：我说我睡眠差。她信了，她信了以后开始替我想办法，她去问她那边的同学，问失眠怎么办，同学告诉她：睡前不要看屏幕，喝一点牛奶，把窗帘拉上。她把这三条原样抄给我，说你今晚试试。我说，好。她说，你试了要告诉我。我说，好。我那天晚上十点四十分把手机扣下了，闭着眼躺了半小时，我没睡着，十一点二十我又拿起来，给她发了一条，说试了，不管用。她说，那你明天再试。我说，好。我撒这个谎的代价是，她那天晚上也很高兴，因为她第一次觉得自己为我做了一件具体的事。我这边中午十二点，她那边凌晨五点，她拿着"我教他怎么睡觉"这一件小事，过了她那一个下午。',-1),e("p",null,"二月有一天夜里，我真熬不住了。那天我发了一场低烧，三十八度二，我吃完药躺下，十点四十就没了意识。她那边下午五点上线，说了四十分钟：她在超市里因为一包米跟人挤了一下；她说她那天忘了带伞，在楼下站了十五分钟；她说她收到一封信，是她家里寄的，她没拆。她说最后那句的时候，语气忽然变了，说她今天不想讲这个，先去上课，晚安。她那边是下午五点四十说的晚安。我第二天早上七点醒，烧退了，看见那四十分钟，我一条一条回，回得很认真。回完我看了一眼时间，我这边七点四十，她那边夜里十二点四十，她睡了。我等到了她那边下午五点。她说，你昨天怎么没在。我说，我睡了。她说，你从来不睡。我说，昨天吃了药。她隔了很久，然后她说了一句我那天真正难受的话：你不会是为了等我，才每天熬到十二点吧。我说，不是。她说，真的？我说，真的，我本来就这个点睡。她说，那你昨天十点四十就没了。我说，我发烧。她说，你发烧了你不跟我说。我说，跟你说了你那边也是凌晨。她说，我他妈在跟你说话。我看到这一句，愣住了——她说脏话的时候很少。她说，我他妈在跟你说话，意思是：你现在正在跟我讲话，你为什么不说。我说，我怕你那晚上要上课。她说，我不上课。她说，我那天下午两点就没课了。她说，我为了跟你说话推了一次小组。我坐在那儿，一句话说不出来，我推掉的那些晚上，她推掉的那些下午，我们两个从来没有碰在一起过。",-1),e("p",null,"我们两个都在为对方不出现在对方的时间里。",-1),e("p",null,'那天晚上她说了一句，说你以后别熬了，我会内疚。我说，好。她说，你说得那么快，你肯定还会熬。我说，我尽量。她说，行，那我以后也在十二点以后不上。我说，你别，你那边是下午。她说，那我也不上。她说，我们两个就都在吃饭的时候不聊天。我说，你别这样。她说，为什么。我说，因为那正好是你最难的时候。她说，你怎么知道我下午五点最难。我说，因为你所有"今天差点坐过站"都是这个点说的。她没回，过了很久，她发了一句，说你连这个都记得。',-1),e("p",null,'那天以后我做了一件事。我开始写草稿，把我那天想跟她说的话，先打在手机的一个备忘录里，不发送，只存着。存到周六晚上十一点，我打开那个备忘录，一条一条挑，挑出来发给她的那几条，叫"能说的"，剩下那一大段，我自己留着。那天晚上我在那个备忘录的第一行写了一句话：这里存的是她那边下午五点我没说的话。那年我十七次打开那个备忘录，一次也没有全发出去。那三十一条里最长的一条有一百六十多个字，那一条我今天还在，它从来没去过她那边。',-1)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
